// 1. 取得上一個節點 (Aggregate 節點) 的資料
const input = $input.first().json;

// 確保資料為陣列格式 (對應 Aggregate 節點輸出的中文 key)
const clients = Array.isArray(input['客戶名稱']) 
  ? input['客戶名稱'] 
  : (input['客戶名稱'] ? [input['客戶名稱']] : []);

const folderLinks = Array.isArray(input['客戶資料夾']) 
  ? input['客戶資料夾'] 
  : (input['客戶資料夾'] ? [input['客戶資料夾']] : []);

const uids = Array.isArray(input['Uid']) 
  ? input['Uid'] 
  : (input['Uid'] ? [input['Uid']] : []);

// 2. 取得 Line Messaging Trigger 的 userId
const userId = $('Start').first().json._firstItem?.source?.userId || '';

// 3. 將資料合併並根據 Uid 排序
let clientList = clients.map((name, index) => {
  return {
    name: name,
    link: folderLinks[index] || '',
    uid: String(uids[index] || '')
  };
});

// 執行排序 (根據 Uid 進行字母與數字升冪排序，如 A21 會排在 B66 前面)
clientList.sort((a, b) => a.uid.localeCompare(b.uid, undefined, { numeric: true, sensitivity: 'base' }));

// LINE Flex Message 按鈕數量安全限制 (上限 10 個，避免超出 LINE 限制導致 400 錯誤)
const maxButtons = clientList.slice(0, 10);

// 4. 動態生成按鈕
const buttons = maxButtons.map((item) => {
  const link = item.link;

  // 串接 uid 參數邏輯
  const finalUri = link.includes('?') 
    ? `${link}&uid=${userId}` 
    : `${link}?uid=${userId}`;

  return {
    "type": "button",
    "action": {
      "type": "uri",
      // LINE label 限制最多 40 字
      "label": String(item.name).substring(0, 40),
      "uri": finalUri
    },
    "style": "primary",
    "margin": "md",
    "color": "#00B900"
  };
});

// 5. 組裝 Flex Message
const flexContent = {
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "📁 雲端資料夾存取",
        "weight": "bold",
        "size": "lg",
        "color": "#1DB446"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "所屬單位的資料夾連結：",
        "size": "md",
        "color": "#666666",
        "wrap": true,
        "margin": "none"
      },
      {
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "spacing": "sm",
        "contents": buttons.length > 0 ? buttons : [
          {
            "type": "text",
            "text": "目前無可用的資料夾連結",
            "color": "#999999",
            "size": "sm"
          }
        ]
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "如誤按請忽略此訊息",
        "size": "xs",
        "color": "#FF0000",
        "align": "center"
      }
    ]
  }
};

return {
  flexJsonString: JSON.stringify(flexContent)
};

