// 1. 取得所有符合的資料列（每一個 item 就是一家公司）
const items = $input.all();

// 2. 取得 Line Messaging Trigger 的 userId 與 replyToken
let userId = "";
let replyToken = "";
try {
  const triggerJson = $('Start').first().json._firstItem;
  userId = triggerJson.source?.userId || "";
  replyToken = triggerJson.replyToken || "";
} catch (e) {
  userId = "";
  replyToken = "";
}

// 3. 把每個 item 轉成 {name, folderId, uid}，並精準擷取 Folder ID
let clientList = items.map((item) => {
  const json = item.json;
  const link = String(json.client_folder || "").trim();

  let folderId = "";
  if (link.includes("folders/")) {
    folderId = link.split("folders/")[1].split("?")[0].split("/")[0].trim();
  } else if (link.includes("id=")) {
    folderId = link.split("id=")[1].split("&")[0].trim();
  } else {
    folderId = link; // 若原本填的就是純 Folder ID
  }

  return {
    name: String(json.client_name || "").trim(),
    folderId: folderId,
    uid: String(json.Uid || "")
  };
}).filter(item => item.name && item.folderId); // 過濾掉空資料

// 執行排序 (根據 Uid 升冪排序)
clientList.sort((a, b) => a.uid.localeCompare(b.uid, undefined, { numeric: true, sensitivity: 'base' }));

// 4. 動態生成按鈕
const buttons = clientList.map((item) => {
  return {
    "type": "button",
    "action": {
      "type": "postback",
      "label": item.name.substring(0, 40),
      "data": `folder_id=${item.folderId}&folder_name=${item.name}`,
      "displayText": `📁 ${item.name}資料夾開啟中，請稍後...`
    },
    "style": "primary",
    "margin": "md",
    "color": "#00B900"
  };
});

// 5. 組裝 Flex Message (多客戶選單用)
const flexContent = {
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "📁 雲端資料夾存取",
        "weight": "bold",
        "size": "lg",
        "color": "#1DB446"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "請選擇欲存取的所屬單位資料夾：",
        "size": "md",
        "color": "#666666",
        "wrap": true,
        "margin": "none"
      },
      {
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "spacing": "sm",
        "contents": buttons
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "點擊公司名稱即可直接瀏覽內部檔案",
        "size": "sm",
        "color": "#888888",
        "align": "center"
      }
    ]
  }
};

// 6. 判斷是否為單一客戶，準備跳過選單所需欄位
const isSingle = clientList.length === 1;

return {
  flexJsonString: JSON.stringify(flexContent),
  flexObject: flexContent,
  onlyOneClient: isSingle,
  replyToken: replyToken,
  folder_id: isSingle ? clientList[0].folderId : "",
  folder_name: isSingle ? clientList[0].name : "",
  company_id: isSingle ? clientList[0].folderId : "",
  company_name: isSingle ? clientList[0].name : ""
};

